func wordBreak(s string, wordDict []string) bool {
	wordMap := map[string]bool{}
	for _, w := range wordDict {
		wordMap[w] = true
	}
	n := len(s)
	dp := make([]bool, n+1)
	dp[0] = true
	for i := 0; i < n; i++ {
		for j := i + 1; j <= n; j++ {
			if dp[i] && wordMap[s[i:j]] {
				dp[j] = true
			}
		}
	}
	return dp[n]
}

func wordBreak(s string, wordDict []string) bool {
	wordMap := map[string]bool{}
	for _, w := range wordDict {
		wordMap[w] = true
	}
	memo := map[string]bool{}
	var backTrack func(sub string) bool
	backTrack = func(sub string) bool {
		if sub == "" {
			return true
		}
		if v, ok := memo[sub]; ok {
			return v
		}
		res := false
		for i := 1; i <= len(sub); i++ {
			if wordMap[sub[:i]] {
				res = backTrack(sub[i:]) || res
			}
		}
		memo[sub] = res
		return res
	}
	return backTrack(s)
}

