def canBreak(start: int, s: str, wordMap: dict) -> bool:
    if start == len(s):
        return True

    for i in range(start + 1, len(s) + 1):
        prefix = s[start:i]
        if prefix in wordMap and canBreak(i, s, wordMap):
            return True

    return False


