def canBreak(start: int, s: str, wordMap: dict, memo: dict) -> bool:
    if start == len(s):
        return True

    if start in memo:
        return memo[start]

    for i in range(start + 1, len(s) + 1):
        prefix = s[start:i]
        if prefix in wordMap and canBreak(i, s, wordMap, memo):
            memo[start] = True
            return True

    memo[start] = False
    return False


