class Solution:
    def wordBreak(self, s: str, wordDict: List[str]) -> bool:
        l = len(s)
        wordMap = {v: True for v in wordDict}
        queue = [0]
        while queue:
            index = queue.pop(0)
            if index == l:
                return True
            for i in range(index + 1, l + 1):
                if s[index:i] in wordMap:
                    queue.append(i)
        return False

class Solution:
    def wordBreak(self, s: str, wordDict: List[str]) -> bool:
        l = len(s)
        wordMap = {v: True for v in wordDict}
        visited = [False] * (l + 1)  # 记录已经访问过的位置，避免重复
        queue = [0]
        while queue:
            index = queue.pop(0)
            if index == l:
                return True
            if visited[index]:
                continue
            visited[index] = True
            for i in range(index + 1, l + 1):
                if s[index:i] in wordMap:
                    queue.append(i)
        return False

class Solution:
